const float M_PI = 3.14159265358979323846264338327950288;
const float M_2_PI = 6.28318530717958647692528676655900576; //M_2_PI = 2 * M_PI
const float M_PI_2 = 1.57079632679489661923132169163975144; //M_PI_2 = M_PI / 2

float casin(float x) {
	float negate = float(x < 0.0);
	x = abs(x);
	float ret = -0.0187293;
	ret *= x;
	ret += 0.0742610;
	ret *= x;
	ret -= 0.2121144;
	ret *= x;
	ret += 1.5707288;
	ret = 3.14159265358979*0.5 - sqrt(1.0 - x)*ret;
	return ret - 2.0 * negate * ret;
}

float atan2(float y, float x) {
 	float absx, absy, val;

     if (x == 0.0 && y == 0.0) {
 		return 0.0;
 	}
 	absy = y < 0.0 ? -y : y;
 	absx = x < 0.0 ? -x : x;
 	if (absy - absx == absy) {
 		return y < 0.0 ? -3.1415*2.0 : 3.1415*2.0;
 	}

    if (absx - absy == absx) {
		val = 0.0;
    } else {
        val = casin((y/x)/sqrt(1.0+((y/x)*(y/x))));
    }
 	if (x > 0.0) {
 		return val;
 	}
 	if (y < 0.0) {
		return val - 3.1415;
 	}
 	return val + 3.1415;
}

float radius = 0.5;
float rotatingSpeed = 1.0;
void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord/iResolution.xy* 2.0) - 1.0;
    uv.x *= iResolution.x / iResolution.y;

    float resizedRadius = radius*(1.0+texelFetch(iChannel0, ivec2(0, 0), 0).r);

    float mask = 1.0 - step(resizedRadius, length(uv));

    vec2 pos = uv/resizedRadius;  

    //vec3 normal = mask*((vec3(pos.x, pos.y, sqrt(1.0-pow(pos.x, 2.0)-pow(pos.y, 2.0)))+ 1.0)* 0.5);
    vec3 normal2 = mask*vec3(pos.x, pos.y, sqrt(1.0-pow(pos.x, 2.0)-pow(pos.y, 2.0)));

    float rotation = rotatingSpeed*iTime;
    vec3 unrotatedCartesianSpherePos = normal2;
    vec3 rotatedCartesianSpherePos;
    rotatedCartesianSpherePos.x = unrotatedCartesianSpherePos.x*cos(rotation) - unrotatedCartesianSpherePos.z*sin(rotation);
    rotatedCartesianSpherePos.y = unrotatedCartesianSpherePos.x*sin(rotation) + unrotatedCartesianSpherePos.z*cos(rotation);
    rotatedCartesianSpherePos.z = unrotatedCartesianSpherePos.y;

    float rho = sqrt(pow(rotatedCartesianSpherePos.x, 2.0)+pow(rotatedCartesianSpherePos.y, 2.0)+pow(rotatedCartesianSpherePos.z, 2.0));
    float phi = atan2(rotatedCartesianSpherePos.z, sqrt(pow(rotatedCartesianSpherePos.x, 2.0)+pow(rotatedCartesianSpherePos.y, 2.0)));
    float theta = atan2(rotatedCartesianSpherePos.y, rotatedCartesianSpherePos.x);
    vec3 rotatedSphericalSpherePos = vec3(rho, phi, theta);

    vec3 scaledRotatedSphericalSpherePos = mask*vec3(rho, (phi+M_PI_2)/M_PI, (theta+M_PI)/M_2_PI);

    vec3 sphericalViewImagePixel = texture(iChannel1, vec2(scaledRotatedSphericalSpherePos.z, scaledRotatedSphericalSpherePos.y)).xyz;

    // Output to screen
    fragColor = mask*vec4(sphericalViewImagePixel, 1.0);
}

// For details on how the keyboard input works, see iq's tutorial: https://www.shadertoy.com/view/lsXGzf

// Numbers are based on JavaScript key codes: https://keycode.info/
const int KEY_LEFT  = 37;
const int KEY_UP    = 38;
const int KEY_RIGHT = 39;
const int KEY_DOWN  = 40;

vec2 handleKeyboard(vec2 offset) {
    float velocity = 1. / 100.; // This will cause offset to change by 0.01 each time an arrow key is pressed

    // texelFetch(iChannel1, ivec2(KEY, 0), 0).x will return a value of one if key is pressed, zero if not pressed
    vec2 left = texelFetch(iChannel1, ivec2(KEY_LEFT, 0), 0).x * vec2(-1, 0);
    vec2 up = texelFetch(iChannel1, ivec2(KEY_UP,0), 0).x * vec2(0, 1);
    vec2 right = texelFetch(iChannel1, ivec2(KEY_RIGHT, 0), 0).x * vec2(1, 0);
    vec2 down = texelFetch(iChannel1, ivec2(KEY_DOWN, 0), 0).x * vec2(0, -1);

    offset += (left + up + right + down) * velocity;

    return offset;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Return the offset value from the last frame (zero if it's first frame)
    vec2 offset = texelFetch( iChannel0, ivec2(0, 0), 0).xy;

    // Pass in the offset of the last frame and return a new offset based on keyboard input
    offset = handleKeyboard(offset);

    // Store offset in the XY values of every pixel value and pass this data to the "Image" shader and the next frame of Buffer A
    fragColor = vec4(offset, 0, 0);
}
